// Drives the docs-write guard both ways on four inputs and reads each
// verdict from the hook's own exit code and its decision JSON. Case D runs
// a pre-fix copy of the guard, so the probe is proved to discriminate
// rather than assumed to: a probe that cannot fail proves nothing.
const { spawnSync } = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');

const GUARD = path.join('plugins', 'claude-kit', 'hooks', 'docs-write-guard.js');
const base = fs.mkdtempSync(path.join(os.tmpdir(), 'guard-probe-'));
const repo = path.join(base, 'repo');
for (const d of ['docs', 'docs/plans', '.kit', 'src']) fs.mkdirSync(path.join(repo, d), { recursive: true });
fs.mkdirSync(path.join(repo, '.git'));

// The pre-fix guard: the deny branch keyed on the file path's spelling
// alone, before the resolved-path check landed. Built from the shipped
// file on a copy, never by editing the shipped file.
const src = fs.readFileSync(GUARD, 'utf8');
const FIXED = '    const under = isUnderDocs(resolved, root);';
if (src.split(FIXED).length - 1 !== 1) throw new Error('anchor not found verbatim');
const PREFIX_GUARD = path.join(base, 'guard.prefix.js');
fs.writeFileSync(PREFIX_GUARD, src.replace(FIXED, '    const under = filePath.replace(/\\\\/g, "/").startsWith("docs/");'), 'utf8');

function run(guard, toolName, filePath, extraEnv) {
    const payload = {
        tool_name: toolName,
        cwd: repo,
        tool_input: { file_path: filePath, content: '# probe\n' }
    };
    return spawnSync(process.execPath, [guard], {
        input: JSON.stringify(payload),
        encoding: 'utf8',
        env: { ...process.env, ...(extraEnv || {}) },
        timeout: 20000
    });
}

function decisionOf(r) {
    if (!r.stdout || r.stdout.trim() === '') return '(no decision JSON)';
    try {
        const parsed = JSON.parse(r.stdout);
        const out = parsed.hookSpecificOutput || {};
        return out.permissionDecision || '(no permissionDecision)';
    } catch (err) {
        return '(decision JSON did not parse: ' + err.message + ')';
    }
}

// Each row: label, guard, tool, path, expected exit, expected decision.
// A is the plain deny. B is the allow for a path outside docs/. C is the
// resolved-path deny, a path spelled outside docs/ that resolves inside it,
// which only the fixed guard sees. D is the same input as C through the
// pre-fix copy, which must allow, or the probe has not discriminated.
const cases = [
    ['A  Write docs/plans/x.md            FIXED   ', GUARD, 'Write', path.join(repo, 'docs', 'plans', 'x.md'), 0, 'deny'],
    ['B  Write src/x.js                   FIXED   ', GUARD, 'Write', path.join(repo, 'src', 'x.js'), 0, 'allow'],
    ['C  Write src/../docs/plans/x.md     FIXED   ', GUARD, 'Write', path.join(repo, 'src', '..', 'docs', 'plans', 'x.md'), 0, 'deny'],
    ['D  Write src/../docs/plans/x.md     PRE-FIX ', PREFIX_GUARD, 'Write', path.join(repo, 'src', '..', 'docs', 'plans', 'x.md'), 0, 'allow']
];

let mismatches = 0;
for (const [label, guard, tool, file, wantExit, wantDecision] of cases) {
    const r = run(guard, tool, file);
    const gotDecision = decisionOf(r);
    const ok = r.status === wantExit && gotDecision === wantDecision;
    if (!ok) mismatches += 1;
    console.log((ok ? 'ok  ' : 'FAIL') + '  ' + label + ' exit ' + r.status + ' (want ' + wantExit + ') decision ' + gotDecision + ' (want ' + wantDecision + ')');
    if (r.stderr && r.stderr.trim() !== '') console.log('        stderr: ' + r.stderr.trim().slice(0, 160));
}

// The exit-code leg on its own, read from the process rather than from a
// pipe: the guard exits 0 on both allow and deny and carries its verdict in
// the decision JSON, so a probe that read only the exit would call every
// case a pass. This block exists to make that reading impossible to make
// by accident: it asserts that A and B share an exit and differ in decision.
const a = run(GUARD, 'Write', path.join(repo, 'docs', 'plans', 'y.md'));
const b = run(GUARD, 'Write', path.join(repo, 'src', 'y.js'));
if (a.status !== b.status) { mismatches += 1; console.log('FAIL  A and B were expected to share an exit code and did not'); }
if (decisionOf(a) === decisionOf(b)) { mismatches += 1; console.log('FAIL  A and B were expected to differ in decision and did not'); }

// The Bash leg: a redirect landing under docs/ is denied, a redirect landing
// under .kit/ is allowed, and a heredoc under docs/ is denied. The guard
// screens these by redirect shape, so an interpreter invoked inline is
// outside what this probe can prove and is left to the tool-name deny.
const bashCases = [
    ['E  Bash echo > docs/notes.md', 'echo hi > docs/notes.md', 'deny'],
    ['F  Bash echo > .kit/notes.md ', 'echo hi > .kit/notes.md', 'allow'],
    ['G  Bash heredoc > docs/x.md  ', 'cat > docs/x.md <<EOT\nhi\nEOT', 'deny']
];
for (const [label, command, wantDecision] of bashCases) {
    const r = spawnSync(process.execPath, [GUARD], {
        input: JSON.stringify({ tool_name: 'Bash', cwd: repo, tool_input: { command } }),
        encoding: 'utf8',
        env: { ...process.env },
        timeout: 20000
    });
    const gotDecision = decisionOf(r);
    const ok = gotDecision === wantDecision;
    if (!ok) mismatches += 1;
    console.log((ok ? 'ok  ' : 'FAIL') + '  ' + label + ' decision ' + gotDecision + ' (want ' + wantDecision + ')');
}

// The Edit leg: the guard screens Edit and MultiEdit by file path exactly as
// it screens Write, so one row per tool under docs/ and one outside it.
for (const tool of ['Edit', 'MultiEdit']) {
    const denied = run(GUARD, tool, path.join(repo, 'docs', 'plans', 'z.md'));
    const allowed = run(GUARD, tool, path.join(repo, 'src', 'z.js'));
    const ok = decisionOf(denied) === 'deny' && decisionOf(allowed) === 'allow';
    if (!ok) mismatches += 1;
    console.log((ok ? 'ok  ' : 'FAIL') + '  H  ' + tool + ' under docs/ then outside it: ' + decisionOf(denied) + ' / ' + decisionOf(allowed) + ' (want deny / allow)');
}

console.log('');
console.log('mismatches: ' + mismatches);
console.log(mismatches === 0
    ? 'DISCRIMINATING: C denies where D (pre-fix) allows on identical input, and every other row matched.'
    : 'NOT PROVEN: at least one row did not match; read the rows above before trusting the guard.');
fs.rmSync(base, { recursive: true, force: true });
process.exitCode = mismatches === 0 ? 0 : 1;
EOF
